rez.kodas_get_markup:
public function get_markup( array $cat_slugs ): float {
    foreach ( $this->priority_order as $slug ) {
        if ( in_array( $slug, $cat_slugs, true ) && isset( $this->category_markups[ $slug ] ) ) {
            return $this->category_markups[ $slug ];
        }
    }
    return $this->default_markup;
}

vf_kodas.get_supplier_discount:
public function get_supplier_discount( string $normalized_brand ): float {
	return $this->supplier_discounts[ $normalized_brand ] ?? 0.0;
}

vf_kodas.get_markup:
public function get_markup( string $normalized_brand, array $cat_slugs ): array {
	// 1. Brand override
	if ( isset( $this->brand_markups[ $normalized_brand ] ) ) {
		return [
			'markup' => $this->brand_markups[ $normalized_brand ],
			'rule'   => 'BRAND:' . $normalized_brand,
		];
	}
	// 2. Category markup
	foreach ( $cat_slugs as $slug ) {
		if ( isset( $this->category_markups[ $slug ] ) ) {
			return [
				'markup' => $this->category_markups[ $slug ],
				'rule'   => 'CAT:' . $slug,
			];
		}
	}
	// 3. Default
	return [ 'markup' => $this->default_markup, 'rule' => 'DEFAULT' ];
}

vf_kodas.apply_supplier_discount:
public function apply_supplier_discount( float $cost, string $normalized_brand ): float {
	$discount = $this->supplier_discounts[ $normalized_brand ] ?? 0.0;
	return $cost * ( 1 - $discount );
}
